SELECT qryVerwendeteMembrantypen.Membrantyp, qryMembranstatistikElOhneLaufzeit.ElementeGesamt, qryMembranstatistikGesamtzahl.ElementeGesamt, qryMembranstatistikPassiv.CountOfGesamtDOL, qryMembranstatistikPassiv.MinOfGesamtDOL, qryMembranstatistikPassiv.MaxOfGesamtDOL, qryMembranstatistikPassiv.AvgOfGesamtDOL, qryMembranstatistikPassiv.StDevOfGesamtDOL, qryMembranstatistikAtiv.CountOfGesamtDOL, qryMembranstatistikAtiv.MinOfGesamtDOL, qryMembranstatistikAtiv.MaxOfGesamtDOL, qryMembranstatistikAtiv.AvgOfGesamtDOL, qryMembranstatistikAtiv.StDevOfGesamtDOL, qryMembranstatistikAlle.CountOfGesamtDOL, qryMembranstatistikAlle.MinOfGesamtDOL, qryMembranstatistikAlle.MaxOfGesamtDOL, qryMembranstatistikAlle.AvgOfGesamtDOL, qryMembranstatistikAlle.StDevOfGesamtDOL
FROM ((((qryVerwendeteMembrantypen LEFT JOIN qryMembranstatistikAlle ON qryVerwendeteMembrantypen.Membrantyp = qryMembranstatistikAlle.Membrantyp) LEFT JOIN qryMembranstatistikAtiv ON qryVerwendeteMembrantypen.Membrantyp = qryMembranstatistikAtiv.Membrantyp) LEFT JOIN qryMembranstatistikPassiv ON qryVerwendeteMembrantypen.Membrantyp = qryMembranstatistikPassiv.Membrantyp) LEFT JOIN qryMembranstatistikGesamtzahl ON qryVerwendeteMembrantypen.Membrantyp = qryMembranstatistikGesamtzahl.Membrantyp) LEFT JOIN qryMembranstatistikElOhneLaufzeit ON qryVerwendeteMembrantypen.Membrantyp = qryMembranstatistikElOhneLaufzeit.Membrantyp;
